def compute(vars):
    average = (vars["v1"] + vars["v2"]) / 2
    return {
        "value": average,
        "trace": {
            "v1": vars["v1"],
            "v2": vars["v2"],
            "average": average,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
